toc
save '../atOut/healthcare_6_4_atomic-Out' WP AT Z X ALPHA BETA SEED N;
WPM{1} = WP; WPM{2} = AT;
BETAM(1)=BETA; BETAM(2) = ALPHA;
WOM{1}=WO; WOM{2}=AN;
[ SM ] = WriteTopicsMult( WPM , BETAM , WOM , 3 , 1.1 , 1 , filename );
